"""Backchannel detection for barge-in with an NLI cross-encoder."""

from __future__ import annotations

import asyncio
import json
import os
import string
from pathlib import Path
from typing import Any, Dict, Optional

import requests
import structlog

from rasa.core.voice.event_composition.handlers.barge_in.verdict import BargeInVerdict
from rasa.exceptions import MissingDependencyException
from rasa.shared.engine.caching import get_local_cache_location

structlogger = structlog.get_logger()

# Chosen on benchmarks/backchannel: a small (70M) zero-shot NLI model, ~15 ms
# per call on one CPU thread.
MODEL_BASE_URL = "https://cdn.rasa.ai/models/deberta-v3-xsmall-zeroshot-v1.1-all-33"
MODEL_FILE = "model_quantized.onnx"
_DOWNLOAD_TIMEOUT_SECONDS = 60
TIMEOUT_SECONDS = 0.2
HYPOTHESIS = (
    "The user briefly acknowledges the assistant while it continues speaking, "
    "without taking the floor."
)

# The user reacts to what they just heard, so only the end of a long utterance is
# useful context; trimming also keeps the pair within the token limit.
_MAX_BOT_TEXT_WORDS = 40
_MAX_TOKENS = 256
_PUNCTUATION_TABLE = str.maketrans("", "", string.punctuation)

_model: Optional[NliModel] = None


class NliModel:
    """An ONNX NLI cross-encoder scoring premise/hypothesis entailment."""

    def __init__(self, session: Any, tokenizer: Any, entailment_index: int) -> None:
        self._session = session
        self._tokenizer = tokenizer
        self._entailment_index = entailment_index
        self._input_names = {model_input.name for model_input in session.get_inputs()}

    def entailment_probability(self, premise: str, hypothesis: str) -> float:
        """Return the softmax probability that ``premise`` entails ``hypothesis``."""
        import numpy as np

        encoding = self._tokenizer.encode(premise, hypothesis)
        feed = {
            "input_ids": np.array([encoding.ids], dtype=np.int64),
            "attention_mask": np.array([encoding.attention_mask], dtype=np.int64),
        }
        if "token_type_ids" in self._input_names:
            feed["token_type_ids"] = np.array([encoding.type_ids], dtype=np.int64)
        logits = self._session.run(None, feed)[0][0]
        exponentials = np.exp(logits - logits.max())
        return float(exponentials[self._entailment_index] / exponentials.sum())


def _download_model_file(base_url: str, file_name: str) -> Path:
    """Download a model file from ``base_url`` unless it is already cached."""
    model_name = base_url.rstrip("/").rsplit("/", 1)[-1]
    model_dir = get_local_cache_location() / "models" / model_name
    target = model_dir / file_name
    if target.is_file():
        return target

    model_dir.mkdir(parents=True, exist_ok=True)
    url = f"{base_url.rstrip('/')}/{file_name}"
    partial = target.with_name(f"{file_name}.{os.getpid()}.part")
    try:
        with requests.get(url, stream=True, timeout=_DOWNLOAD_TIMEOUT_SECONDS) as r:
            r.raise_for_status()
            with open(partial, "wb") as out_file:
                for chunk in r.iter_content(chunk_size=1 << 20):
                    out_file.write(chunk)
        os.replace(partial, target)
    finally:
        partial.unlink(missing_ok=True)
    return target


def load_nli_model(base_url: str, model_file: str) -> NliModel:
    """Download (if needed) and load an NLI cross-encoder from the Rasa CDN.

    Raises:
        MissingDependencyException: When the model runtime packages are missing.
    """
    try:
        import onnxruntime
        from tokenizers import Tokenizer
    except ImportError:
        raise MissingDependencyException(
            "Backchannel detection needs onnxruntime and tokenizers."
        ) from None

    structlogger.info(
        "barge_in.nli_model.loading", model=base_url, model_file=model_file
    )
    tokenizer_path = _download_model_file(base_url, "tokenizer.json")
    tokenizer = Tokenizer.from_file(str(tokenizer_path))
    tokenizer.enable_truncation(max_length=_MAX_TOKENS)
    tokenizer.no_padding()
    with open(_download_model_file(base_url, "config.json")) as config_file:
        id2label = json.load(config_file)["id2label"]
    entailment_index = next(
        int(index) for index, label in id2label.items() if label.lower() == "entailment"
    )
    options = onnxruntime.SessionOptions()
    # One thread per inference keeps concurrent calls from oversubscribing the
    # CPU shared with the event loop.
    options.intra_op_num_threads = 1
    options.inter_op_num_threads = 1
    session = onnxruntime.InferenceSession(
        str(_download_model_file(base_url, model_file)),
        options,
        providers=["CPUExecutionProvider"],
    )
    return NliModel(session, tokenizer, entailment_index)


def warm_up() -> None:
    """Load the backchannel model for the first voice conversation.

    Loading on the first barge-in would exceed the time budget. A model that
    cannot be loaded does not stop the conversation: speech shorter than
    ``min_words`` then never interrupts the bot.
    """
    global _model
    if _model is not None:
        return
    try:
        _model = load_nli_model(MODEL_BASE_URL, MODEL_FILE)
    except Exception as error:
        structlogger.error(
            "barge_in.nli_model_unavailable",
            event_info="Speech shorter than 'min_words' will not interrupt the bot.",
            error=str(error),
            error_type=type(error).__name__,
        )


def loaded_model() -> Optional[NliModel]:
    """Return the model loaded by :func:`warm_up`, if any."""
    return _model


def build_premise(transcript: str, bot_text: Optional[str]) -> str:
    """Describe the exchange as an NLI premise.

    Without bot text, "the user interrupts" biases the model against the
    backchannel hypothesis, so the speech is framed as happening during playback.
    """
    if not bot_text:
        return f'While the assistant is talking, the user says: "{transcript}"'
    bot_text = " ".join(bot_text.split()[-_MAX_BOT_TEXT_WORDS:])
    return f'The assistant says: "{bot_text}" The user interrupts: "{transcript}"'


class BackchannelDetector:
    """Decide whether user speech during bot playback is a barge-in.

    Speech of at least ``min_words`` words is accepted without a model call.
    Shorter speech is ignored as a backchannel when the model scores
    ``HYPOTHESIS`` at or above ``threshold``, and accepted otherwise. If
    the model is unavailable, fails, or is too slow, shorter speech is ignored.
    """

    def __init__(
        self,
        model: Optional[NliModel],
        min_words: int,
        threshold: float,
        timeout_seconds: float = TIMEOUT_SECONDS,
    ) -> None:
        self._model = model
        self._min_words = min_words
        self._threshold = threshold
        self._timeout_seconds = timeout_seconds

    async def detect(self, transcript: str, bot_text: Optional[str]) -> BargeInVerdict:
        """Return the barge-in verdict for ``transcript`` heard during ``bot_text``."""
        word_count = len(transcript.translate(_PUNCTUATION_TABLE).split())
        metadata: Dict[str, Any] = {
            "word_count": word_count,
            "min_words": self._min_words,
        }
        if word_count >= self._min_words:
            return BargeInVerdict(
                accepted=True, reason="word_threshold_reached", metadata=metadata
            )

        premise = build_premise(transcript, bot_text)
        try:
            if self._model is None:
                raise MissingDependencyException("Backchannel model is not loaded.")
            score = await asyncio.wait_for(
                asyncio.to_thread(
                    self._model.entailment_probability, premise, HYPOTHESIS
                ),
                self._timeout_seconds,
            )
        # Barge-in runs inside live calls: an unusable model must degrade to the
        # word-count rule rather than abort event composition for the call.
        except Exception as error:
            error_type = type(error).__name__
            structlogger.warning(
                "barge_in.nli_detector.fallback", error_type=error_type
            )
            return BargeInVerdict(
                accepted=False,
                reason="below_min_words",
                description=(
                    f"fewer than {self._min_words} words; "
                    f"backchannel model unavailable ({error_type})"
                ),
                metadata={**metadata, "nli_fallback_error": error_type},
            )

        metadata.update(
            backchannel_score=round(score, 4),
            backchannel_threshold=self._threshold,
            has_bot_text=bot_text is not None,
        )
        if score >= self._threshold:
            return BargeInVerdict(
                accepted=False,
                reason="backchannel",
                description=f"backchannel (score {score:.2f} ≥ {self._threshold:.2f})",
                metadata=metadata,
            )
        return BargeInVerdict(
            accepted=True,
            reason="not_backchannel",
            description=(
                f"not a backchannel (score {score:.2f} < {self._threshold:.2f})"
            ),
            metadata=metadata,
        )
